def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count numbers in [low, high] with equally many even and odd digits,
    divisible by k.
    """
    def count_at_most(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = [int(c) for c in str(bound)]
        length = len(digits)

        # State tracks the signed digit-count difference (even minus odd),
        # the remainder modulo k, and whether a non-leading digit has begun.
        from functools import lru_cache

        @lru_cache(None)
        def dp(pos: int, balance: int, remainder: int, started: bool, tight: bool) -> int:
            if pos == length:
                return int(started and balance == 0 and remainder == 0)

            limit = digits[pos] if tight else 9
            total = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == limit
                if not started and digit == 0:
                    total += dp(pos + 1, balance, remainder, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += dp(pos + 1, next_balance, next_remainder, True, next_tight)
            return total

        return dp(0, 0, 0, False, True)

    return count_at_most(high) - count_at_most(low - 1)

def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """Count monotone paths in the grid that avoid the forbidden rectangle."""
    mod = 998244353
    limit = W + H + 4

    fact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i - 1] * i % mod
    inv_fact = [1] * (limit + 1)
    inv_fact[limit] = pow(fact[limit], mod - 2, mod)
    for i in range(limit, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % mod

    def choose(n: int, k: int) -> int:
        if n < 0 or k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % mod * inv_fact[n - k] % mod

    def paths_to(x: int, y: int) -> int:
        # Paths from any grid point at or below/left of (x,y) to it.
        if x < 0 or y < 0:
            return 0
        return (choose(x + y + 2, x + 1) - 1) % mod

    def prefix_sum(x: int, y: int) -> int:
        # Sum paths_to(a,b) for 0 <= a <= x, 0 <= b <= y.
        if x < 0 or y < 0:
            return 0
        return (choose(x + y + 4, x + 2) - (y + 4) - (x + 1) * (y + 1)) % mod

    def rect_sum(x1: int, x2: int, y1: int, y2: int) -> int:
        if x1 > x2 or y1 > y2:
            return 0
        return (prefix_sum(x2, y2) - prefix_sum(x1 - 1, y2)
                - prefix_sum(x2, y1 - 1) + prefix_sum(x1 - 1, y1 - 1)) % mod

    # All unrestricted paths whose start is outside the hole.
    starts_outside = (
        prefix_sum(W, H)
        - rect_sum(W - R, W - L, H - U, H - D)
    ) % mod

    # Remove paths from outside that enter the hole. Each such path is
    # counted once at its first forbidden point.
    hit_paths = 0
    corner_prefix = paths_to(L - 1, D) + paths_to(L, D - 1)
    hit_paths += corner_prefix * paths_to(W - L, H - D)

    if L > 0:
        for y in range(D + 1, U + 1):
            hit_paths += paths_to(L - 1, y) * paths_to(W - L, H - y)
    if D > 0:
        for x in range(L + 1, R + 1):
            hit_paths += paths_to(x, D - 1) * paths_to(W - x, H - D)

    return (starts_outside - hit_paths) % mod

