MOD = 998244353


def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """ Given a string s of length n consisting of 'A', 'B', 'C', and '?', count the number
    of ways to replace each '?' with 'A', 'B', or 'C' such that the resulting string contains
    at least k "good strings" as contiguous substrings.

    A "good string" is a non-empty string that can be turned into an empty string by:
    - Operation 1: Choose two identical characters and delete them
    - Operation 2: Choose one A, one B, and one C and delete them

    Substrings at different positions are counted separately even if they are identical.
    Return the count modulo 998244353.
    """
    if k <= 0:
        return pow(3, s.count("?"), MOD)
    if k > n * (n + 1) // 2:
        return 0

    # Deletability depends only on the three character counts modulo 2.
    # The counts must have equal parity: use triples to make their residual
    # counts even, then remove pairs.
    #
    # Equivalently, a substring is good exactly when its prefix parity states
    # are equal up to toggling all three bits. This gives four state classes.
    # Count walks together with the four class visit counts. The number of good
    # substrings is the sum of choose(visit_count, 2) over those classes.
    dp = {((1, 0, 0, 0), 0): 1}
    for ch in s:
        nxt = {}
        for (counts, cur), ways in dp.items():
            if ch == "?":
                targets = ((cur + 1) & 3, (cur + 2) & 3, (cur + 3) & 3)
            else:
                bit = 1 << (ord(ch) - ord("A"))
                # Classes are represented by choosing the parity vector whose
                # C bit is zero; vectors differing by 111 are equivalent.
                # Directly compute the class transition by XOR then normalize.
                target = _normalize(cur ^ bit)
                targets = (target,)
            for target in targets:
                updated = list(counts)
                updated[target] += 1
                key = (tuple(updated), target)
                nxt[key] = (nxt.get(key, 0) + ways) % MOD
        dp = nxt

    return sum(
        ways
        for (counts, _), ways in dp.items()
        if sum(c * (c - 1) // 2 for c in counts) >= k
    ) % MOD


def _normalize(state: int) -> int:
    # Four quotient states are represented by the low two parity bits:
    # (a,b,c) and its complement share the same class.
    if state & 4:
        state ^= 7
    return state

