def max_partitions_with_one_change(s: str, k: int) -> int:
    """Return the maximum greedy partition count after at most one substitution."""
    n = len(s)
    # next_pos[i][c] is the first occurrence of letter c at or after i.
    next_pos = [[n] * 26 for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        next_pos[i] = next_pos[i + 1].copy()
        next_pos[i][ord(s[i]) - 97] = i

    # Greedy suffix partition counts for an unmodified suffix.
    suffix = [0] * (n + 1)
    end = 0
    counts = [0] * 26
    distinct = 0
    for start in range(n):
        while end < n:
            c = ord(s[end]) - 97
            if counts[c] == 0 and distinct == k:
                break
            if counts[c] == 0:
                distinct += 1
            counts[c] += 1
            end += 1
        suffix[start] = 1 + suffix[end]
        c = ord(s[start]) - 97
        counts[c] -= 1
        if counts[c] == 0:
            distinct -= 1
    # At each index, retain the greedy prefix's completed partition count and
    # distinct-letter set in its currently open partition.
    completed = 0
    state = set()
    best = suffix[0]
    for i, ch in enumerate(s):
        original = ord(ch) - 97
        # A changed letter already in the current partition has no effect.
        candidates = range(26)
        for replacement in candidates:
            if replacement == original:
                continue
            pref_completed = completed
            letters = state
            if replacement not in state and len(state) == k:
                # The changed character begins a new partition.
                pref_completed += 1
                letters = {replacement}
            else:
                letters = state | {replacement}

            # Find the first position after i that introduces too many new
            # letters to this partition. Its character begins the next one.
            needed = k - len(letters) + 1
            positions = sorted(
                next_pos[i + 1][c] for c in range(26)
                if c not in letters and next_pos[i + 1][c] < n
            )
            if len(positions) >= needed:
                boundary = positions[needed - 1]
                total = pref_completed + 1 + suffix[boundary]
            else:
                total = pref_completed + 1
            if total > best:
                best = total

        # Advance the unmodified greedy prefix state through s[i].
        c = original
        if c not in state and len(state) == k:
            completed += 1
            state = {c}
        else:
            state.add(c)

    return best

MOD = 998244353


def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """ Given a string s of length n consisting of 'A', 'B', 'C', and '?', count the number
    of ways to replace each '?' with 'A', 'B', or 'C' such that the resulting string contains
    at least k "good strings" as contiguous substrings.

    A "good string" is a non-empty string that can be turned into an empty string by:
    - Operation 1: Choose two identical characters and delete them
    - Operation 2: Choose one A, one B, and one C and delete them

    Substrings at different positions are counted separately even if they are identical.
    Return the count modulo 998244353.
    """
    if k <= 0:
        return pow(3, s.count("?"), MOD)
    if k > n * (n + 1) // 2:
        return 0

    # Deletability depends only on the three character counts modulo 2.
    # The counts must have equal parity. Prefix parity states differing by
    # 111 are equivalent, leaving four quotient states.
    dp = {((1, 0, 0, 0), 0): 1}
    for ch in s:
        nxt = {}
        for (counts, cur), ways in dp.items():
            if ch == "?":
                targets = (cur ^ 1, cur ^ 2, cur ^ 3)
            else:
                bit = 1 << (ord(ch) - ord("A"))
                targets = (_normalize(cur ^ bit),)
            for target in targets:
                updated = list(counts)
                updated[target] += 1
                key = (tuple(updated), target)
                nxt[key] = (nxt.get(key, 0) + ways) % MOD
        dp = nxt

    return sum(
        ways
        for (counts, _), ways in dp.items()
        if sum(c * (c - 1) // 2 for c in counts) >= k
    ) % MOD


def _normalize(state: int) -> int:
    # Canonical representative of a parity vector modulo (1, 1, 1).
    if state & 4:
        state ^= 7
    return state

