from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Find a non-empty subsequence with alternating sum k and maximum product <= limit."""
    # For each (alternating sum, next sign), retain every attainable in-limit
    # product: a smaller product can still lead to a better result after a
    # later multiplication. Over-limit products only matter if a zero later
    # resets their product to zero, so track their existence separately.
    dp = {}
    over = set()

    for x in nums:
        next_dp = {state: products.copy() for state, products in dp.items()}
        next_over = set(over)

        # A new subsequence may begin at this element (its index in the
        # subsequence is even, so it contributes positively).
        if x <= limit:
            next_dp.setdefault((x, 1), set()).add(x)
        else:
            next_over.add((x, 1))

        for (total, length_parity), products in dp.items():
            # Appending contributes with a minus sign after an odd-length
            # prefix and with a plus sign after an even-length prefix.
            new_total = total - x if length_parity else total + x
            new_parity = 1 - length_parity
            target = (new_total, new_parity)
            out = next_dp.setdefault(target, set())
            for product in products:
                candidate = product * x
                if candidate <= limit:
                    out.add(candidate)
                else:
                    next_over.add(target)

        for total, length_parity in over:
            new_total = total - x if length_parity else total + x
            target = (new_total, 1 - length_parity)
            if x == 0:
                next_dp.setdefault(target, set()).add(0)
            else:
                next_over.add(target)

        dp, over = next_dp, next_over

    answer = -1
    for (total, _), products in dp.items():
        if total == k and products:
            answer = max(answer, max(products))
    return answer

def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """Count monotone paths in the grid that avoid the forbidden rectangle."""
    mod = 998244353
    limit = W + H + 4

    fact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i - 1] * i % mod
    inv_fact = [1] * (limit + 1)
    inv_fact[limit] = pow(fact[limit], mod - 2, mod)
    for i in range(limit, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % mod

    def choose(n: int, k: int) -> int:
        if n < 0 or k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % mod * inv_fact[n - k] % mod

    def paths_to(x: int, y: int) -> int:
        # Paths from any grid point at or below/left of (x,y) to it.
        if x < 0 or y < 0:
            return 0
        return (choose(x + y + 2, x + 1) - 1) % mod

    def prefix_sum(x: int, y: int) -> int:
        # Sum paths_to(a,b) for 0 <= a <= x, 0 <= b <= y.
        if x < 0 or y < 0:
            return 0
        return (choose(x + y + 4, x + 2) - (y + 3) - (x + 1) * (y + 2)) % mod

    def rect_sum(x1: int, x2: int, y1: int, y2: int) -> int:
        if x1 > x2 or y1 > y2:
            return 0
        return (prefix_sum(x2, y2) - prefix_sum(x1 - 1, y2)
                - prefix_sum(x2, y1 - 1) + prefix_sum(x1 - 1, y1 - 1)) % mod

    # All unrestricted paths whose start is outside the hole.
    starts_outside = (
        prefix_sum(W, H)
        - rect_sum(W - R, W - L, H - U, H - D)
    ) % mod

    # Remove paths from outside that enter the hole. Each such path is
    # counted once at its first forbidden point.
    hit_paths = 0
    corner_prefix = paths_to(L - 1, D) + paths_to(L, D - 1)
    hit_paths += corner_prefix * paths_to(W - L, H - D)

    if L > 0:
        for y in range(D + 1, U + 1):
            hit_paths += paths_to(L - 1, y) * paths_to(W - L, H - y)
    if D > 0:
        for x in range(L + 1, R + 1):
            hit_paths += paths_to(x, D - 1) * paths_to(W - x, H - D)

    return (starts_outside - hit_paths) % mod

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the wallpaper rectangle."""
    # Each integer unit square is either uniformly colored or bisected by a
    # diagonal. The doubled contribution therefore depends only on the square's
    # coordinates modulo four.
    def count_residue(start: int, stop: int, residue: int) -> int:
        return (stop - 1 - residue) // 4 - (start - 1 - residue) // 4

    xs = [count_residue(A, C, r) for r in range(4)]
    ys = [count_residue(B, D, r) for r in range(4)]

    total = 0
    for i in range(4):
        for j in range(4):
            if (i + j) % 2:
                weight = 1
            else:
                color_parity = i + j // 2 + (i + j) // 2
                weight = 2 if color_parity % 2 == 0 else 0
            total += xs[i] * ys[j] * weight
    return total

