def max_partitions_with_one_change(s: str, k: int) -> int:
    """ Given a string s and an integer k, determine the maximum number of partitions possible
    after optionally changing at most one character in s to another lowercase letter.

    The partitioning process works as follows:
    - Choose the longest prefix of s containing at most k distinct characters
    - Remove this prefix (counting as one partition)
    - Repeat until s is empty
    """
    n = len(s)
    next_pos = [[n] * 26 for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        next_pos[i] = next_pos[i + 1].copy()
        next_pos[i][ord(s[i]) - 97] = i

    # Compute each greedy segment's exclusive end, then suffix counts.
    end_at = [0] * n
    end = 0
    counts = [0] * 26
    distinct = 0
    for start in range(n):
        while end < n:
            c = ord(s[end]) - 97
            if counts[c] == 0 and distinct == k:
                break
            if counts[c] == 0:
                distinct += 1
            counts[c] += 1
            end += 1
        end_at[start] = end
        c = ord(s[start]) - 97
        counts[c] -= 1
        if counts[c] == 0:
            distinct -= 1
    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = 1 + suffix[end_at[i]]

    completed = 0
    state = set()
    best = suffix[0]
    for i, ch in enumerate(s):
        original = ord(ch) - 97
        for replacement in range(26):
            if replacement == original:
                continue
            if replacement not in state and len(state) == k:
                pref_completed = completed + 1
                letters = {replacement}
            else:
                pref_completed = completed
                letters = state | {replacement}
            needed = k - len(letters) + 1
            positions = sorted(
                next_pos[i + 1][c] for c in range(26)
                if c not in letters and next_pos[i + 1][c] < n
            )
            if len(positions) >= needed:
                total = pref_completed + 1 + suffix[positions[needed - 1]]
            else:
                total = pref_completed + 1
            best = max(best, total)

        c = original
        if c not in state and len(state) == k:
            completed += 1
            state = {c}
        else:
            state.add(c)
    return best

