def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding walks of K moves starting at any empty cell."""
    if K < 0:
        return 0
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == "."]
    if len(cells) <= K:
        return 0

    # Map each usable cell to an index and precompute its grid neighbors.
    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            j = index.get((nr, nc))
            if j is not None:
                neighbors[i].append(j)

    total = 0

    def walk(cell: int, visited: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        count = 0
        for nxt in neighbors[cell]:
            bit = 1 << nxt
            if not visited & bit:
                count += walk(nxt, visited | bit, remaining - 1)
        return count

    for start in range(len(cells)):
        total += walk(start, 1 << start, K)
    return total

from functools import lru_cache
from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Determine the winner when each index must be selected at least once."""
    if n == 1:
        return "Fennec"

    # Once the pass supply is sufficiently large, only its parity matters.
    # Keep both parities at the saturation boundary.
    cap = 2 * n + 2

    def capped(value: int) -> int:
        if value <= cap:
            return value
        return cap if value % 2 == 0 else cap - 1

    if n <= 18:
        @lru_cache(maxsize=None)
        def winning(mask: int, passes: int) -> bool:
            if mask.bit_count() == 1:
                return True

            if passes and not winning(mask, passes - 1):
                return True

            bits = mask
            while bits:
                bit = bits & -bits
                i = bit.bit_length() - 1
                bits -= bit
                next_passes = capped(passes + a[i] - 1)
                if not winning(mask ^ bit, next_passes):
                    return True
            return False

        return "Fennec" if winning((1 << n) - 1, 0) else "Snuke"

    parity = sum((x - 1) & 1 for x in a) & 1
    return "Fennec" if ((n + parity) & 1) else "Snuke"

