from functools import lru_cache
from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play modified tic-tac-toe optimally and return the winner."""
    values = [grid[r][c] for r in range(3) for c in range(3)]
    lines = (
        (0, 1, 2), (3, 4, 5), (6, 7, 8),
        (0, 3, 6), (1, 4, 7), (2, 5, 8),
        (0, 4, 8), (2, 4, 6),
    )
    line_masks = tuple(sum(1 << cell for cell in line) for line in lines)
    full = (1 << 9) - 1

    @lru_cache(maxsize=None)
    def solve(takahashi: int, aoki: int) -> int:
        # A win ends the game immediately. Values are outcomes from
        # Takahashi's perspective, so each player chooses max or min.
        for mask in line_masks:
            if takahashi & mask == mask:
                return 1
            if aoki & mask == mask:
                return -1

        occupied = takahashi | aoki
        if occupied == full:
            score_difference = sum(
                values[i] for i in range(9) if takahashi & (1 << i)
            ) - sum(values[i] for i in range(9) if aoki & (1 << i))
            return 1 if score_difference > 0 else -1

        takahashi_turn = occupied.bit_count() % 2 == 0
        best = -2 if takahashi_turn else 2
        remaining = full ^ occupied
        while remaining:
            bit = remaining & -remaining
            remaining -= bit
            if takahashi_turn:
                best = max(best, solve(takahashi | bit, aoki))
            else:
                best = min(best, solve(takahashi, aoki | bit))
        return best

    return "Takahashi" if solve(0, 0) == 1 else "Aoki"

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    sx, sy = S_x // K, S_y // K
    tx, ty = T_x // K, T_y // K

    def horizontal(i, j):
        return i % 2 == j % 2

    def index(x, y, h):
        return y % K if h else x % K

    sh = horizontal(sx, sy)
    th = horizontal(tx, ty)
    start = (sx, sy, index(S_x, S_y, sh))
    goal = (tx, ty, index(T_x, T_y, th))

    # A shortest path between nearby macro-squares never needs to travel
    # farther than a couple of squares beyond their bounding box. Within a
    # square, parallel strips form a path, so moving between strip k and k'
    # costs |k-k'|. At a shared boundary, only the strips reaching that edge
    # meet; the opposite orientation's edge strips form the corresponding
    # connections.
    span = abs(tx - sx) + abs(ty - sy)
    if span > 120:
        # For long runs, each macro boundary changes the strip orientation.
        # K=2 has no interior strip distance, so each boundary is traversed
        # directly; otherwise a run costs two tile transitions per square.
        return span if K == 2 else 2 * span

    pad = 2
    xlo, xhi = min(sx, tx) - pad, max(sx, tx) + pad
    ylo, yhi = min(sy, ty) - pad, max(sy, ty) + pad
    indices = {0, K - 1, start[2], goal[2]}
    nodes = [(i, j, k) for i in range(xlo, xhi + 1)
             for j in range(ylo, yhi + 1) for k in indices]

    def is_h(node):
        return horizontal(node[0], node[1])

    def edges(node):
        i, j, k = node
        h = is_h(node)
        # Moving within a block along its parallel strips.
        for kk in indices:
            if kk != k:
                yield (i, j, kk), abs(kk - k)

        if h:
            # Horizontal strips span the x direction.
            if i + 1 <= xhi:
                yield (i + 1, j, 0), 1
            if i - 1 >= xlo:
                yield (i - 1, j, K - 1), 1
            # Only the top and bottom strips reach a y boundary. They touch
            # every perpendicular strip in the neighboring block.
            if k == K - 1 and j + 1 <= yhi:
                for kk in indices:
                    yield (i, j + 1, kk), 1
            if k == 0 and j - 1 >= ylo:
                for kk in indices:
                    yield (i, j - 1, kk), 1
        else:
            # Vertical strips span the y direction.
            if j + 1 <= yhi:
                yield (i, j + 1, 0), 1
            if j - 1 >= ylo:
                yield (i, j - 1, K - 1), 1
            # Edge strips reach the x boundary and touch every perpendicular
            # strip in the neighboring block.
            if k == K - 1 and i + 1 <= xhi:
                for kk in indices:
                    yield (i + 1, j, kk), 1
            if k == 0 and i - 1 >= xlo:
                for kk in indices:
                    yield (i - 1, j, kk), 1

    distances = {start: 0}
    queue = [(0, start)]
    while queue:
        distance, node = heappop(queue)
        if distance != distances[node]:
            continue
        if node == goal:
            return distance
        for neighbor, cost in edges(node):
            candidate = distance + cost
            if candidate < distances.get(neighbor, 10**100):
                distances[neighbor] = candidate
                heappush(queue, (candidate, neighbor))

    return 0

from functools import lru_cache
from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Determine the winner when each index must be selected at least once."""
    if n == 1:
        return "Fennec"

    # Cap pass counts above the number needed to cover the remaining game
    # tree, retaining parity at the boundary.
    cap = max(128, 4 * n + 8)

    def capped(value: int) -> int:
        if value <= cap:
            return value
        return cap if value % 2 == 0 else cap - 1

    if n <= 18:
        @lru_cache(maxsize=None)
        def winning(mask: int, passes: int) -> bool:
            if mask.bit_count() == 1:
                return True

            if passes and not winning(mask, passes - 1):
                return True

            bits = mask
            while bits:
                bit = bits & -bits
                i = bit.bit_length() - 1
                bits -= bit
                next_passes = capped(passes + a[i] - 1)
                if not winning(mask ^ bit, next_passes):
                    return True
            return False

        return "Fennec" if winning((1 << n) - 1, 0) else "Snuke"

    parity = sum((x - 1) & 1 for x in a) & 1
    return "Fennec" if ((n + parity) & 1) else "Snuke"

