def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    from collections import deque

    def locate(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return (i, j, y - j * K)
        return (i, j, x - i * K)

    start, goal = locate(S_x, S_y), locate(T_x, T_y)
    if start == goal:
        return 0
    if abs(start[0] - goal[0]) + abs(start[1] - goal[1]) > 100:
        return (abs(T_x - S_x) + abs(T_y - S_y) + K - 1) // K

    def neighbors(node):
        i, j, k = node
        even = (i + j) % 2 == 0
        if k:
            yield (i, j, k - 1)
        if k + 1 < K:
            yield (i, j, k + 1)
        if even:
            # Across vertical sides, every horizontal tile meets the edge strip.
            yield (i - 1, j, K - 1)
            yield (i + 1, j, 0)
            # Across horizontal sides only the boundary tile reaches the edge.
            if k == 0:
                for q in range(K):
                    yield (i, j - 1, q)
            if k == K - 1:
                for q in range(K):
                    yield (i, j + 1, q)
        else:
            # Vertical strips each meet either horizontal boundary.
            for q in range(K):
                if k == 0:
                    yield (i - 1, j, q)
                    yield (i, j - 1, q)
                if k == K - 1:
                    yield (i + 1, j, q)
                    yield (i, j + 1, q)
            # The side strips meet every tile in neighboring even cells.
            if k == 0:
                for q in range(K):
                    yield (i - 1, j, q)
            if k == K - 1:
                for q in range(K):
                    yield (i + 1, j, q)

    todo = deque([(start, 0)])
    seen = {start}
    while todo:
        node, dist = todo.popleft()
        for nxt in neighbors(node):
            if nxt == goal:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                todo.append((nxt, dist + 1))
    return (abs(T_x - S_x) + abs(T_y - S_y) + K - 1) // K

from math import isqrt


def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a^b for a >= 1 and b >= 2."""
    if n < 1:
        return 0

    count = isqrt(n)

    def integer_root(value: int, exponent: int) -> int:
        """Return floor(value ** (1 / exponent)) using integer arithmetic."""
        lo = 1
        hi = 1 << ((value.bit_length() + exponent - 1) // exponent)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** exponent <= value:
                lo = mid
            else:
                hi = mid - 1
        return lo

    # Enumerate all powers with exponent >= 3. Squares are already counted;
    # the set removes overlaps among different bases and exponents.
    extra = set()
    for exponent in range(3, n.bit_length()):
        max_base = integer_root(n, exponent)
        for base in range(2, max_base + 1):
            value = base ** exponent
            root = isqrt(value)
            if root * root != value:
                extra.add(value)

    return count + len(extra)

