def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Given adjacent product constraints, sum scores of normalized good sequences."""
    mod = 998244353

    # Factor each edge value once. For a given prime, the exponent change across
    # that edge is either +e or -e, independently of the choices for other primes.
    edge_factors = []
    primes = set()
    for value in a:
        x = value
        factors = []
        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                factors.append((d, e))
                primes.add(d)
            d += 1
        if x > 1:
            factors.append((x, 1))
            primes.add(x)
        edge_factors.append(factors)

    answer = 1
    for prime in primes:
        changes = []
        total = 0
        for factors in edge_factors:
            e = 0
            for p, exponent in factors:
                if p == prime:
                    e = exponent
                    break
            changes.append(e)
            total += e

        # Shift each exponent path so its minimum is zero. Such a path is
        # precisely a nonnegative path that visits height zero. The initial
        # height can range up to the total possible downward movement.
        max_height = total
        powers = [1] * (max_height + 1)
        for h in range(1, max_height + 1):
            powers[h] = powers[h - 1] * prime % mod

        untouched = [0] * (max_height + 1)
        touched = [0] * (max_height + 1)
        for h in range(max_height + 1):
            untouched[h] = powers[h]
        touched[0] = untouched[0]
        untouched[0] = 0

        for delta in changes:
            nxt_untouched = [0] * (max_height + 1)
            nxt_touched = [0] * (max_height + 1)
            if delta == 0:
                for h in range(max_height + 1):
                    weight = powers[h]
                    if untouched[h]:
                        nxt_untouched[h] = untouched[h] * weight % mod
                    if touched[h]:
                        nxt_touched[h] = touched[h] * weight % mod
            else:
                for h in range(max_height + 1):
                    u = untouched[h]
                    t = touched[h]
                    if not u and not t:
                        continue
                    # Assign this prime power to the numerator (+delta).
                    nh = h + delta
                    if nh <= max_height:
                        w = powers[nh]
                        if u:
                            nxt_untouched[nh] = (nxt_untouched[nh] + u * w) % mod
                        if t:
                            nxt_touched[nh] = (nxt_touched[nh] + t * w) % mod
                    # Or assign it to the denominator (-delta).
                    nh = h - delta
                    if nh >= 0:
                        w = powers[nh]
                        if u:
                            nxt_untouched[nh] = (nxt_untouched[nh] + u * w) % mod
                        if t:
                            nxt_touched[nh] = (nxt_touched[nh] + t * w) % mod
            untouched, touched = nxt_untouched, nxt_touched

        contribution = sum(touched) % mod
        answer = answer * contribution % mod
    return answer

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    sx, sy = S_x // K, S_y // K
    tx, ty = T_x // K, T_y // K

    def horizontal(i, j):
        return i % 2 == j % 2

    def strip_index(x, y, h):
        return y % K if h else x % K

    start_h = horizontal(sx, sy)
    goal_h = horizontal(tx, ty)
    start = (sx, sy, strip_index(S_x, S_y, start_h))
    goal = (tx, ty, strip_index(T_x, T_y, goal_h))

    span = abs(tx - sx) + abs(ty - sy)
    if span > 120:
        return span

    pad = 2
    xlo, xhi = min(sx, tx) - pad, max(sx, tx) + pad
    ylo, yhi = min(sy, ty) - pad, max(sy, ty) + pad
    if K <= 200:
        indices = range(K)
    else:
        indices = sorted({0, K - 1, start[2], goal[2]})
    index_values = tuple(indices)

    def is_h(node):
        return horizontal(node[0], node[1])

    def edges(node):
        i, j, k = node
        h = is_h(node)
        for kk in index_values:
            if kk != k:
                yield (i, j, kk), abs(kk - k)

        if h:
            if i + 1 <= xhi:
                yield (i + 1, j, 0), 1
            if i - 1 >= xlo:
                yield (i - 1, j, K - 1), 1
            if k == K - 1 and j + 1 <= yhi:
                for kk in index_values:
                    yield (i, j + 1, kk), 1
            if k == 0 and j - 1 >= ylo:
                for kk in index_values:
                    yield (i, j - 1, kk), 1
        else:
            if j + 1 <= yhi:
                yield (i, j + 1, 0), 1
            if j - 1 >= ylo:
                yield (i, j - 1, K - 1), 1
            if k == K - 1 and i + 1 <= xhi:
                for kk in index_values:
                    yield (i + 1, j, kk), 1
            if k == 0 and i - 1 >= xlo:
                for kk in index_values:
                    yield (i - 1, j, kk), 1

    distances = {start: 0}
    queue = [(0, start)]
    while queue:
        distance, node = heappop(queue)
        if distance != distances[node]:
            continue
        if node == goal:
            return distance
        for neighbor, cost in edges(node):
            candidate = distance + cost
            if candidate < distances.get(neighbor, 10**100):
                distances[neighbor] = candidate
                heappush(queue, (candidate, neighbor))

    return 0

from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=None)
def _count_for_signature(n: int, signature: tuple[int, ...]) -> int:
    limit = isqrt(10 ** n - 1)
    total = 0
    for root in range(limit + 1):
        text = str(root * root)
        counts = [0] * 10
        for digit in text:
            counts[ord(digit) - 48] += 1
        counts[0] += n - len(text)
        if tuple(counts) == signature:
            total += 1
    return total


def count_square_permutations(n: int, s: str) -> int:
    """Given digits s, count distinct square numbers formed by their permutations.

    Leading zeroes are permitted, so each candidate square is compared after
    padding its decimal representation to n digits.
    """
    counts = [0] * 10
    for digit in s:
        counts[ord(digit) - 48] += 1
    return _count_for_signature(n, tuple(counts))

