from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equally many even and odd digits
    that are divisible by k.
    """
    def count_up_to(limit: int) -> int:
        if limit <= 0:
            return 0

        digits = tuple(map(int, str(limit)))

        @lru_cache(maxsize=None)
        def dp(pos: int, remainder: int, balance: int, started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and balance == 0 and remainder == 0)

            ceiling = digits[pos] if tight else 9
            total = 0
            for digit in range(ceiling + 1):
                next_tight = tight and digit == ceiling
                if not started and digit == 0:
                    total += dp(pos + 1, remainder, balance, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += dp(pos + 1, next_remainder, next_balance, True, next_tight)
            return total

        return dp(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

from functools import lru_cache
from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play modified tic-tac-toe optimally and return the winner."""
    values = [grid[r][c] for r in range(3) for c in range(3)]
    lines = (
        (0, 1, 2), (3, 4, 5), (6, 7, 8),
        (0, 3, 6), (1, 4, 7), (2, 5, 8),
        (0, 4, 8), (2, 4, 6),
    )
    line_masks = tuple(sum(1 << cell for cell in line) for line in lines)
    full = (1 << 9) - 1
    # Any line win must be preferred to any completed-board score.
    win_value = 10**30

    @lru_cache(maxsize=None)
    def solve(takahashi: int, aoki: int) -> int:
        for mask in line_masks:
            if takahashi & mask == mask:
                return win_value
            if aoki & mask == mask:
                return -win_value

        occupied = takahashi | aoki
        if occupied == full:
            return sum(values[i] for i in range(9) if takahashi & (1 << i)) - sum(
                values[i] for i in range(9) if aoki & (1 << i)
            )

        takahashi_turn = occupied.bit_count() % 2 == 0
        remaining = full ^ occupied
        if takahashi_turn:
            return max(solve(takahashi | (1 << i), aoki) for i in range(9)
                       if remaining & (1 << i))
        return min(solve(takahashi, aoki | (1 << i)) for i in range(9)
                   if remaining & (1 << i))

    return "Takahashi" if solve(0, 0) > 0 else "Aoki"

