from functools import lru_cache
from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive integer sequences with product at most N
    whose product has divisor sum divisible by 3, modulo 998244353.
    """
    if N < 1 or M < 1:
        return 0

    # For a number n = prod(p**e), the number of ordered M-factorizations
    # is prod(C(M+e-1, e)).
    # sigma(n) is divisible by 3 iff at least one local sigma(p**e) is.
    # The complementary ("bad") exponents are: p=3 arbitrary;
    # p=1 mod 3: e != 2 mod 3; p=2 mod 3: e even.
    root = isqrt(N)
    small_primes = []
    sieve = bytearray(b"\x01") * (root + 1)
    if root >= 0:
        sieve[0: min(2, root + 1)] = b"\x00" * min(2, root + 1)
    for p in range(2, root + 1):
        if sieve[p]:
            small_primes.append(p)
            if p * p <= root:
                sieve[p * p: root + 1: p] = b"\x00" * (((root - p * p) // p) + 1)

    # Quotient values floor(N/i), sufficient for every recursive bound x/p.
    vals = []
    i = 1
    while i <= N:
        v = N // i
        vals.append(v)
        i = N // v
        i += 1
    # vals generated in descending order; use a direct map for all lookups.
    index = {v: j for j, v in enumerate(vals)}
    g = [[0] * len(vals) for _ in range(3)]

    def residue_count(v, r):
        if v < 2:
            return 0
        # Number in [1,v] congruent to r, with 1 excluded.
        c = (v + (2 - r)) // 3
        if r == 1:
            c -= 1
        return c

    for j, v in enumerate(vals):
        for r in range(3):
            g[r][j] = residue_count(v, r)

    # Prefix counts of primes by residue before the current sieve prime.
    pref = [0, 0, 0]
    for p in small_primes:
        if p * p > N:
            break
        if p == 3:
            for j, v in enumerate(vals):
                if v >= 9:
                    y = v // 3
                    # Remove 3*m, m >= 3; g contains integers m >= 2.
                    removed = sum(g[r][index[y]] for r in range(3))
                    if y >= 2:
                        removed -= 1  # m=2 is below the current prime.
                    g[0][j] -= removed
        else:
            inv = 1 if p % 3 == 1 else 2
            for j, v in enumerate(vals):
                if v < p * p:
                    break
                y = v // p
                iy = index[y]
                iprev = pref[(0 - 0) % 3]  # unused, keeps update explicit below
                for r in range(3):
                    src = (r * inv) % 3
                    # At this stage g(src, p-1) consists of earlier primes.
                    prior = 0
                    # Only prime 2 can precede p among the sieve primes here.
                    # Use the maintained class prefix for all earlier primes.
                    prior = pref[src]
                    g[r][j] -= g[src][iy] - prior
        pref[p % 3] += 1

    def prime_count(x, r):
        if x < 2:
            return 0
        # All x used here are quotient values or <= root.
        j = index.get(x)
        if j is not None:
            return g[r][j]
        # For small endpoint queries, use the sieve directly.
        if x <= root:
            return sum(1 for p in small_primes if p <= x and p % 3 == r)
        # Recursive bounds are quotient values; this is only a defensive path.
        y = N // (N // x)
        j = index.get(y)
        return g[r][j]

    def total_prime_count(x):
        return sum(prime_count(x, r) for r in range(3))

    # Combination weights C(M+e-1,e), built only as far as log_2 N.
    max_e = N.bit_length()
    comb = [1] * (max_e + 1)
    for e in range(1, max_e + 1):
        comb[e] = comb[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    def summatory(bad):
        @lru_cache(None)
        def rec(x, last):
            if x <= 1:
                return 1
            ans = 1
            # Primes greater than sqrt(x) occur only as a single prime.
            lo = isqrt(x) + 1
            if bad:
                ans += M * (prime_count(x, 1) - prime_count(lo - 1, 1))
                if lo <= 3 <= x:
                    ans += M
            else:
                ans += M * (total_prime_count(x) - total_prime_count(lo - 1))
            # Select the least prime factor p <= sqrt(x), its full exponent,
            # then recurse on factors strictly larger than p.
            for p in small_primes:
                if p <= last:
                    continue
                if p * p > x:
                    break
                pmod = p % 3
                power = p
                e = 1
                while power <= x:
                    allowed = True
                    if bad:
                        if p == 3:
                            allowed = True
                        elif pmod == 1:
                            allowed = e % 3 != 2
                        else:
                            allowed = e % 2 == 0
                    if allowed:
                        ans += comb[e] * rec(x // power, p)
                    e += 1
                    if power > x // p:
                        break
                    power *= p
            return ans % MOD
        return rec(N, 1)

    return (summatory(False) - summatory(True)) % MOD

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between adjacent tiles."""
    from collections import deque

    def locate(x, y):
        i, j = x // K, y // K
        return (i, j, y - j * K) if (i + j) % 2 == 0 else (i, j, x - i * K)

    start, goal = locate(S_x, S_y), locate(T_x, T_y)
    if start == goal:
        return 0
    dx, dy = abs(start[0] - goal[0]), abs(start[1] - goal[1])
    if dx + dy > 100:
        # A monotone route crosses one cell boundary per move at this scale.
        return (abs(T_x - S_x) + abs(T_y - S_y) + K - 1) // K

    def candidates(i, j):
        vals = {0, K - 1}
        if (i, j) == goal[:2]:
            vals.add(goal[2])
        return vals

    def neighbors(n):
        i, j, k = n
        even = (i + j) % 2 == 0
        if k:
            yield (i, j, k - 1)
        if k < K - 1:
            yield (i, j, k + 1)
        if even:
            yield (i - 1, j, K - 1)
            yield (i + 1, j, 0)
            if k == 0:
                for q in candidates(i, j - 1):
                    yield (i, j - 1, q)
            if k == K - 1:
                for q in candidates(i, j + 1):
                    yield (i, j + 1, q)
        else:
            # Each vertical strip spans the cell height and meets the
            # boundary strip in the even cell on either side.
            yield (i, j - 1, 0)
            yield (i, j + 1, K - 1)
            if k == 0:
                for q in candidates(i - 1, j):
                    yield (i - 1, j, q)
            if k == K - 1:
                for q in candidates(i + 1, j):
                    yield (i + 1, j, q)

    todo = deque([(start, 0)])
    seen = {start}
    while todo:
        node, dist = todo.popleft()
        for nxt in neighbors(node):
            if nxt == goal:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                todo.append((nxt, dist + 1))
    return (abs(T_x - S_x) + abs(T_y - S_y) + K - 1) // K

