from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=None)
def _count_for_signature(n: int, signature: tuple[int, ...]) -> int:
    limit = isqrt(10 ** n - 1)
    total = 0
    for root in range(limit + 1):
        text = str(root * root)
        # The n-digit permutation may represent a smaller square with any
        # number of leading zeroes.
        counts = [0] * 10
        for digit in text:
            counts[ord(digit) - 48] += 1
        counts[0] += n - len(text)
        if tuple(counts) == signature:
            total += 1
    return total


def count_square_permutations(n: int, s: str) -> int:
    """Count distinct square values obtainable by permuting the given digits."""
    counts = [0] * 10
    for digit in s:
        counts[ord(digit) - 48] += 1
    return _count_for_signature(n, tuple(counts))

