def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences of orientations of the specified graph.

    The in-degree contributions from the two cycle edges at vertex i are
    determined by the direction of the preceding and following cycle edges.
    Treating those edge directions as two hidden states gives a two-state
    automaton whose output at i is d_i. We count output strings by tracking
    the Boolean relation between the initial and current hidden states.
    There are only 16 such relations, so the dynamic program is linear in n.
    """
    mod = 998244353

    # A relation is encoded as two row bitmasks: bits 0..1 for row 0,
    # bits 2..3 for row 1. For each possible spoke bit and output degree,
    # store the relation from the preceding edge direction to the next one.
    transitions = []
    for spoke in (0, 1):
        by_degree = []
        for degree in range(4):
            relation = 0
            for before in (0, 1):
                for after in (0, 1):
                    cycle_in = before + 1 - after
                    if degree - cycle_in in (0, spoke):
                        relation |= 1 << (before * 2 + after)
            by_degree.append(relation)
        transitions.append(by_degree)

    # Compose an accumulated relation with a one-step transition relation.
    compose = [[0] * 16 for _ in range(16)]
    for left in range(16):
        for right in range(16):
            out = 0
            for start in (0, 1):
                for middle in (0, 1):
                    if left & (1 << (start * 2 + middle)):
                        for end in (0, 1):
                            if right & (1 << (middle * 2 + end)):
                                out |= 1 << (start * 2 + end)
            compose[left][right] = out

    # Identity relation: either starting edge direction can persist.
    dp = [0] * 16
    dp[9] = 1
    for bit in s:
        opts = transitions[bit == "1"]
        nxt = [0] * 16
        for relation, count in enumerate(dp):
            if count:
                for step in opts:
                    result = compose[relation][step]
                    nxt[result] = (nxt[result] + count) % mod
        dp = nxt

    # The final hidden state must equal the initial state for the cycle to close.
    return sum(count for relation, count in enumerate(dp)
               if relation & 0b1001) % mod

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black-painted area in the given rectangle.

    The wallpaper is bounded by x=n, y=even n, and x+y=even n, with the
    region containing (0.5, 0.5) black.
    """
    # In x strip i <= x < i+1, color changes at x+y=2m.  This
    # integrates black area in a fundamental 4-by-2 tile.
    def below_sum(x0: float, x1: float, y1: float, z: float) -> float:
        """Area in [x0,x1] x [0,y1] where x+y < z."""
        def sq(v: float) -> float:
            return max(v, 0.0) ** 2
        return 0.5 * (sq(z - x0) - sq(z - x1)
                      - sq(z - x0 - y1) + sq(z - x1 - y1))

    def base_prefix(x: float, y: float) -> float:
        result = 0.0
        for i in range(4):
            lo = float(i)
            hi = min(x, float(i + 1))
            if hi <= lo:
                continue
            for m in range(3):
                if (i + m) % 2 == 0:
                    result += (below_sum(lo, hi, y, 2.0 * m + 2.0)
                               - below_sum(lo, hi, y, 2.0 * m))
        return result

    tile = base_prefix(4.0, 2.0)

    def primitive(x: int, y: int) -> float:
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)
        return (qx * qy * tile
                + qx * base_prefix(4.0, float(ry))
                + qy * base_prefix(float(rx), 2.0)
                + base_prefix(float(rx), float(ry)))

    area = (primitive(C, D) - primitive(A, D)
            - primitive(C, B) + primitive(A, B))
    return round(2 * area)

