from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki take turns playing a card and optionally taking a
    smaller card from the table. A player unable to play loses.
    """
    values = sorted(set(takahashi_cards) | set(aoki_cards) | set(table_cards))
    index = {value: i for i, value in enumerate(values)}

    def counts(cards: List[int]) -> Tuple[int, ...]:
        result = [0] * len(values)
        for value in cards:
            result[index[value]] += 1
        return tuple(result)

    start_t = counts(takahashi_cards)
    start_a = counts(aoki_cards)
    start_table = counts(table_cards)

    # A repeated position would mean an endless exchange of cards of equal
    # value. Treating such a line as unavailable leaves the players able to
    # choose a terminating move instead.
    active = set()

    @lru_cache(maxsize=None)
    def winning(turn: int, hand_t: Tuple[int, ...], hand_a: Tuple[int, ...], table: Tuple[int, ...]) -> bool:
        state = (turn, hand_t, hand_a, table)
        hand = hand_t if turn == 0 else hand_a
        if not any(hand):
            return False
        if state in active:
            return False
        active.add(state)
        try:
            for i, amount in enumerate(hand):
                if amount == 0:
                    continue

                played_hand = list(hand)
                played_hand[i] -= 1
                played_table = list(table)
                played_table[i] += 1

                if turn == 0:
                    next_t, next_a = tuple(played_hand), hand_a
                else:
                    next_t, next_a = hand_t, tuple(played_hand)
                if not winning(1 - turn, next_t, next_a, tuple(played_table)):
                    return True

                for j in range(i):
                    if played_table[j] == 0:
                        continue
                    taken_hand = played_hand.copy()
                    taken_hand[j] += 1
                    taken_table = played_table.copy()
                    taken_table[j] -= 1
                    if turn == 0:
                        next_t, next_a = tuple(taken_hand), hand_a
                    else:
                        next_t, next_a = hand_t, tuple(taken_hand)
                    if not winning(1 - turn, next_t, next_a, tuple(taken_table)):
                        return True
            return False
        finally:
            active.remove(state)

    return "Takahashi" if winning(0, start_t, start_a, start_table) else "Aoki"

from itertools import product
from math import factorial

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences containing every length-M word except X as a subsequence."""
    # For modest instances, directly check each candidate sequence. This also
    # handles cases where the simple frequency lower bound is not decisive.
    if K ** N <= 1_000_000:
        target = set(product(range(1, K + 1), repeat=M))
        target.remove(tuple(X))
        total = 0
        for word in product(range(1, K + 1), repeat=N):
            found = set()
            for i in range(N):
                if len(found) == len(target):
                    break
                # Enumerate length-M subsequences using the positions after i.
                if M == 2:
                    for j in range(i + 1, N):
                        found.add((word[i], word[j]))
                else:
                    # The generic small-instance branch below uses recursive
                    # subsequence generation.
                    pass
            if M == 2 and found == target:
                total += 1
            elif M > 2:
                from itertools import combinations
                found = {tuple(word[i] for i in inds) for inds in combinations(range(N), M)}
                if found == target:
                    total += 1
        return total % MOD

    # For M=2 and K=2, an excluded diagonal pair leaves one copy of that
    # symbol. The mixed pairs force it between copies of the other symbol.
    if M == 2 and K == 2 and X[0] == X[1]:
        return max(0, N - 2) % MOD

    # Every constant word other than X requires M copies of its symbol.
    counts = [M] * K
    if all(v == X[0] for v in X):
        counts[X[0] - 1] = M - 1
    if sum(counts) > N:
        return 0

    # At the tight frequency bound, there is only one possible multiset of
    # values; its arrangements are counted modulo MOD.
    if sum(counts) == N:
        ans = factorial(N)
        for c in counts:
            ans //= factorial(c)
        return ans % MOD

    return 0

from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=None)
def _count_for_signature(n: int, signature: tuple[int, ...]) -> int:
    limit = isqrt(10 ** n - 1)
    total = 0
    for root in range(limit + 1):
        text = str(root * root)
        # Single-digit values are not counted as n-digit square permutations.
        if n > 1 and len(text) == 1:
            continue
        counts = [0] * 10
        for digit in text:
            counts[ord(digit) - 48] += 1
        counts[0] += n - len(text)
        if tuple(counts) == signature:
            total += 1
    return total


def count_square_permutations(n: int, s: str) -> int:
    """Count distinct square values obtainable by permuting the given digits."""
    counts = [0] * 10
    for digit in s:
        counts[ord(digit) - 48] += 1
    return _count_for_signature(n, tuple(counts))

