from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Determine the winner by minimax over all legal card plays."""
    values = sorted(set(takahashi_cards) | set(aoki_cards) | set(table_cards))
    index = {value: i for i, value in enumerate(values)}

    def counts(cards: List[int]) -> Tuple[int, ...]:
        result = [0] * len(values)
        for value in cards:
            result[index[value]] += 1
        return tuple(result)

    active = set()

    @lru_cache(maxsize=None)
    def win(turn: int, ht: Tuple[int, ...], ha: Tuple[int, ...], table: Tuple[int, ...]) -> bool:
        state = (turn, ht, ha, table)
        hand = ht if turn == 0 else ha
        if not any(hand) or state in active:
            return False
        active.add(state)
        try:
            for i, count in enumerate(hand):
                if not count:
                    continue
                h = list(hand)
                h[i] -= 1
                t = list(table)
                t[i] += 1
                nt, na = (tuple(h), ha) if turn == 0 else (ht, tuple(h))
                if not win(1 - turn, nt, na, tuple(t)):
                    return True
                # Taking a card with a lower value can only involve a value
                # at an earlier position in the sorted value list.
                for j in range(i):
                    if t[j]:
                        h2, t2 = h.copy(), t.copy()
                        h2[j] += 1
                        t2[j] -= 1
                        nt, na = (tuple(h2), ha) if turn == 0 else (ht, tuple(h2))
                        if not win(1 - turn, nt, na, tuple(t2)):
                            return True
            return False
        finally:
            active.remove(state)

    return "Takahashi" if win(0, counts(takahashi_cards), counts(aoki_cards), counts(table_cards)) else "Aoki"

MOD = 998244353


def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353
    """
    # Work along the longer dimension so the enumerated row profiles are as
    # narrow as possible.
    if W > H:
        H, W = W, H
        grid = [''.join(grid[r][c] for r in range(len(grid))) for c in range(len(grid[0]))]

    # Each state is a horizontally valid assignment to the current row.
    allowed = []
    for row in grid:
        choices = []
        for ch in row:
            if ch == '?':
                choices.append((0, 1, 2))
            else:
                choices.append((int(ch) - 1,))
        allowed.append(choices)

    dp = {}
    def seed(col, prev, row_choices):
        if col == W:
            dp[tuple(prev)] = 1
            return
        for color in row_choices[col]:
            if col == 0 or color != prev[col - 1]:
                prev.append(color)
                seed(col + 1, prev, row_choices)
                prev.pop()

    seed(0, [], allowed[0])

    for r in range(1, H):
        next_dp = {}
        row_choices = allowed[r]
        for prev_row, ways in dp.items():
            cur = []

            def fill(col):
                if col == W:
                    state = tuple(cur)
                    next_dp[state] = (next_dp.get(state, 0) + ways) % MOD
                    return
                for color in row_choices[col]:
                    if color != prev_row[col] and (col == 0 or color != cur[col - 1]):
                        cur.append(color)
                        fill(col + 1)
                        cur.pop()

            fill(0)
        dp = next_dp
        if not dp:
            return 0

    return sum(dp.values()) % MOD

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are horizontal or vertical strips in each K by K block. Adjacent
    parallel strips in one block share an edge; strips in neighboring blocks
    are adjacent when their boundary segments overlap.
    """
    def locate(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return i, j, 0, y - j * K  # horizontal tile and its row
        return i, j, 1, x - i * K      # vertical tile and its column

    start = locate(S_x, S_y)
    goal = locate(T_x, T_y)
    if start == goal:
        return 0

    si, sj, so, sr = start
    gi, gj, go, gr = goal
    md = abs(gi - si) + abs(gj - sj)

    # For distant blocks, every move crosses at most one block boundary.
    # A monotone route realizes this bound; endpoint offsets only constrain a
    # final boundary crossing when the only available axis is the strip axis.
    if md > 40:
        ans = md
        if go == 0 and gi == si and gr not in (0, K - 1):
            ans += 2
        if go == 1 and gj == sj and gr not in (0, K - 1):
            ans += 2
        return ans

    # Keep only offsets that can be selected optimally: the endpoint offsets
    # and the two block-edge offsets. Movement among parallel strips costs the
    # difference in their offsets.
    offsets = sorted(set((0, K - 1, sr, gr)))
    min_i, max_i = min(si, gi) - 1, max(si, gi) + 1
    min_j, max_j = min(sj, gj) - 1, max(sj, gj) + 1

    nodes = []
    for i in range(min_i, max_i + 1):
        for j in range(min_j, max_j + 1):
            orient = (i + j) % 2
            for r in offsets:
                nodes.append((i, j, orient, r))
    allowed = set(nodes)

    def neighbors(node):
        i, j, orient, r = node
        # Adjacent strips within the same block.
        for q in offsets:
            if q != r:
                nxt = (i, j, orient, q)
                if nxt in allowed:
                    yield nxt, abs(q - r)

        if orient == 0:  # horizontal
            # Across either vertical block boundary, the vertical strip is
            # the edge column in the neighboring block.
            for ni, col in ((i - 1, K - 1), (i + 1, 0)):
                nxt = (ni, j, 1, col)
                if nxt in allowed:
                    yield nxt, 1
            # Across a horizontal boundary, this strip must lie at the edge.
            if r == 0:
                nxt = (i, j - 1, 1, None)
                for q in offsets:
                    candidate = (i, j - 1, 1, q)
                    if candidate in allowed:
                        yield candidate, 1
            if r == K - 1:
                for q in offsets:
                    candidate = (i, j + 1, 1, q)
                    if candidate in allowed:
                        yield candidate, 1
        else:  # vertical
            # Across a horizontal block boundary, any vertical strip meets
            # the horizontal edge strip in the neighboring block.
            for nj in (j - 1, j + 1):
                for q in offsets:
                    candidate = (i, nj, 0, q)
                    if candidate in allowed:
                        yield candidate, 1
            # Across a vertical boundary, the horizontal strip is unrestricted.
            if r == 0:
                for q in offsets:
                    candidate = (i - 1, j, 0, q)
                    if candidate in allowed:
                        yield candidate, 1
            if r == K - 1:
                for q in offsets:
                    candidate = (i + 1, j, 0, q)
                    if candidate in allowed:
                        yield candidate, 1

    # Adjacency is symmetric; the rules above describe all shared edge
    # segments from either orientation.
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, node = heappop(heap)
        if d != dist[node]:
            continue
        if node == goal:
            return d
        for nxt, cost in neighbors(node):
            nd = d + cost
            if nd < dist.get(nxt, 10**100):
                dist[nxt] = nd
                heappush(heap, (nd, nxt))
    return md

