from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Find the winner under optimal play of the card game."""
    values = sorted(set(takahashi_cards) | set(aoki_cards) | set(table_cards))
    indices = {value: i for i, value in enumerate(values)}

    def counts(cards: List[int]) -> Tuple[int, ...]:
        result = [0] * len(values)
        for value in cards:
            result[indices[value]] += 1
        return tuple(result)

    path = set()

    @lru_cache(maxsize=None)
    def wins(turn: int, t_hand: Tuple[int, ...], a_hand: Tuple[int, ...], table: Tuple[int, ...]) -> bool:
        state = (turn, t_hand, a_hand, table)
        hand = t_hand if turn == 0 else a_hand
        if not any(hand) or state in path:
            return False
        path.add(state)
        try:
            for i, count in enumerate(hand):
                if not count:
                    continue
                h = list(hand)
                h[i] -= 1
                tbl = list(table)
                tbl[i] += 1
                nt, na = (tuple(h), a_hand) if turn == 0 else (t_hand, tuple(h))
                if not wins(1 - turn, nt, na, tuple(tbl)):
                    return True
                for j in range(i + 1):
                    if tbl[j] == 0:
                        continue
                    h2, tbl2 = h.copy(), tbl.copy()
                    h2[j] += 1
                    tbl2[j] -= 1
                    nt, na = (tuple(h2), a_hand) if turn == 0 else (t_hand, tuple(h2))
                    if not wins(1 - turn, nt, na, tuple(tbl2)):
                        return True
            return False
        finally:
            path.remove(state)

    return "Takahashi" if wins(0, counts(takahashi_cards), counts(aoki_cards), counts(table_cards)) else "Aoki"

