from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Determine the winner by minimax over all legal card plays."""
    values = sorted(set(takahashi_cards) | set(aoki_cards) | set(table_cards))
    index = {value: i for i, value in enumerate(values)}

    def counts(cards: List[int]) -> Tuple[int, ...]:
        result = [0] * len(values)
        for value in cards:
            result[index[value]] += 1
        return tuple(result)

    @lru_cache(maxsize=None)
    def win(turn: int, ht: Tuple[int, ...], ha: Tuple[int, ...], table: Tuple[int, ...]) -> bool:
        hand = ht if turn == 0 else ha
        if not any(hand):
            return False
        for i, count in enumerate(hand):
            if not count:
                continue
            h = list(hand)
            h[i] -= 1
            tbl = list(table)
            tbl[i] += 1
            nt, na = (tuple(h), ha) if turn == 0 else (ht, tuple(h))
            if not win(1 - turn, nt, na, tuple(tbl)):
                return True
            for j in range(i):
                if tbl[j]:
                    h2, tbl2 = h.copy(), tbl.copy()
                    h2[j] += 1
                    tbl2[j] -= 1
                    nt, na = (tuple(h2), ha) if turn == 0 else (ht, tuple(h2))
                    if not win(1 - turn, nt, na, tuple(tbl2)):
                        return True
        return False

    return "Takahashi" if win(0, counts(takahashi_cards), counts(aoki_cards), counts(table_cards)) else "Aoki"

