from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if n != len(tiles):
        n = len(tiles)
    target_area = h * w
    areas = [a * b for a, b in tiles]

    # A necessary condition: some subset of the tiles has exactly the board's area.
    subset_sums = {0}
    for area in areas:
        subset_sums |= {s + area for s in tuple(subset_sums)}
    if target_area not in subset_sums:
        return False

    # Each row is represented by a bit mask of occupied cells.
    full = (1 << w) - 1
    orientations = []
    for a, b in tiles:
        choices = {(a, b), (b, a)}
        orientations.append(tuple(sorted(choices)))

    @lru_cache(maxsize=None)
    def search(rows: Tuple[int, ...], remaining: int) -> bool:
        # Find the first empty cell in row-major order.
        row = col = -1
        for r, bits in enumerate(rows):
            if bits != full:
                row = r
                col = next(c for c in range(w) if not (bits >> c) & 1)
                break
        if row < 0:
            return True

        empty = target_area - sum(bits.bit_count() for bits in rows)
        # Remaining tiles must contain a subset with area equal to the uncovered area.
        possible = {0}
        for i, area in enumerate(areas):
            if remaining >> i & 1:
                possible |= {s + area for s in tuple(possible)}
        if empty not in possible:
            return False

        for i in range(len(tiles)):
            if not (remaining >> i) & 1:
                continue
            for th, tw in orientations[i]:
                if row + th > h or col + tw > w:
                    continue
                mask = ((1 << tw) - 1) << col
                if any(rows[rr] & mask for rr in range(row, row + th)):
                    continue
                updated = list(rows)
                for rr in range(row, row + th):
                    updated[rr] |= mask
                if search(tuple(updated), remaining ^ (1 << i)):
                    return True
        return False

    return search((0,) * h, (1 << len(tiles)) - 1)

from functools import lru_cache


@lru_cache(maxsize=None)
def _beautiful_nozero_exact(length: int) -> int:
    """Count beautiful numbers with exactly length digits and no zero digits."""
    answer = 0
    for target in range(1, 9 * length + 1):
        # (digit sum, digit product modulo target) -> number of prefixes
        states = {(0, 1 % target): 1}
        for _ in range(length):
            next_states = {}
            for (digit_sum, remainder), count in states.items():
                max_digit = min(9, target - digit_sum)
                for digit in range(1, max_digit + 1):
                    key = (digit_sum + digit, remainder * digit % target)
                    next_states[key] = next_states.get(key, 0) + count
            states = next_states
        answer += states.get((target, 0), 0)
    return answer


@lru_cache(maxsize=None)
def _beautiful_nozero_upto(bound: int) -> int:
    """Count beautiful, zero-free numbers from 1 through bound."""
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    length = len(digits)
    answer = sum(_beautiful_nozero_exact(k) for k in range(1, length))
    for target in range(1, 9 * length + 1):
        # The bool in each key records whether the prefix still equals bound.
        states = {(0, 1 % target, True): 1}
        for pos, limit_digit in enumerate(digits):
            next_states = {}
            remaining = length - pos - 1
            for (digit_sum, remainder, tight), count in states.items():
                upper = limit_digit if tight else 9
                for digit in range(1, upper + 1):
                    new_sum = digit_sum + digit
                    if new_sum > target or new_sum + 9 * remaining < target:
                        continue
                    new_tight = tight and digit == limit_digit
                    key = (new_sum, remainder * digit % target, new_tight)
                    next_states[key] = next_states.get(key, 0) + count
            states = next_states
        answer += states.get((target, 0, False), 0)
        answer += states.get((target, 0, True), 0)
    return answer


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    def prefix(n: int) -> int:
        if n <= 0:
            return 0
        # Every number containing a zero has digit product zero and is beautiful.
        digits = len(str(n))
        zero_free_total = sum(9 * (10 ** (k - 1)) for k in range(1, digits))
        zero_free_total += sum(1 for _ in str(n) if _ != "0") if False else 0
        # Count zero-free numbers of the top length that do not exceed n.
        d = tuple(map(int, str(n)))
        count_top = 0
        for pos, bound_digit in enumerate(d):
            low = 1
            high = bound_digit - 1
            if pos == 0:
                low = 1
            for digit in range(low, high + 1):
                remaining = len(d) - pos - 1
                count_top += 9 ** remaining
            if bound_digit == 0:
                break
        else:
            count_top += 1
        zero_free_total += count_top
        return n - zero_free_total + _beautiful_nozero_upto(n)

    return prefix(r) - prefix(l - 1)

from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    n = len(tiles)
    target_area = h * w
    areas = [a * b for a, b in tiles]
    subset_sums = {0}
    for area in areas:
        subset_sums |= {s + area for s in tuple(subset_sums)}
    if target_area not in subset_sums:
        return False

    full = (1 << w) - 1
    orientations = [tuple(sorted({(a, b), (b, a)})) for a, b in tiles]

    @lru_cache(maxsize=None)
    def search(rows: Tuple[int, ...], remaining: int) -> bool:
        row = col = -1
        for r, bits in enumerate(rows):
            if bits != full:
                row = r
                col = next(c for c in range(w) if not (bits >> c) & 1)
                break
        if row < 0:
            return True

        empty = target_area - sum(bits.bit_count() for bits in rows)
        possible = {0}
        for i, area in enumerate(areas):
            if remaining >> i & 1:
                possible |= {s + area for s in tuple(possible)}
        if empty not in possible:
            return False

        for i in range(n):
            if not (remaining >> i) & 1:
                continue
            for th, tw in orientations[i]:
                # Try every placement of this rectangle that covers the first
                # uncovered cell. Row-major order usually makes its origin the
                # first empty cell, but enumerating origins keeps the exact-cover
                # condition explicit even when the uncovered region has holes.
                for top in range(max(0, row - th + 1), row + 1):
                    for left in range(max(0, col - tw + 1), col + 1):
                        if top + th > h or left + tw > w:
                            continue
                        mask = ((1 << tw) - 1) << left
                        if any(rows[rr] & mask for rr in range(top, top + th)):
                            continue
                        updated = list(rows)
                        for rr in range(top, top + th):
                            updated[rr] |= mask
                        if search(tuple(updated), remaining ^ (1 << i)):
                            return True
        return False

    return search((0,) * h, (1 << n) - 1)

