def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the minimum adjacency distance between the containing tiles."""
    def locate(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return i, j, 0, y - j * K
        return i, j, 1, x - i * K

    start = locate(S_x, S_y)
    goal = locate(T_x, T_y)
    if start == goal:
        return 0

    si, sj, so, sr = start
    gi, gj, go, gr = goal
    md = abs(gi - si) + abs(gj - sj)

    if md > 40:
        ans = md
        # A strip can only leave through its short-axis boundary. For a route
        # confined to that axis, moving to the boundary costs the offset.
        if so == 0 and gi == si and gj != sj:
            ans += min(sr, K - 1 - sr)
        elif so == 1 and gj == sj and gi != si:
            ans += min(sr, K - 1 - sr)
        if go == 0 and gi == si and gr not in (0, K - 1):
            ans += 2
        elif go == 1 and gj == sj and gr not in (0, K - 1):
            ans += 2
        return ans

    offsets = sorted(set((0, K - 1, sr, gr)))
    min_i, max_i = min(si, gi) - 1, max(si, gi) + 1
    min_j, max_j = min(sj, gj) - 1, max(sj, gj) + 1

    allowed = {
        (i, j, (i + j) % 2, r)
        for i in range(min_i, max_i + 1)
        for j in range(min_j, max_j + 1)
        for r in offsets
    }

    def neighbors(node):
        i, j, orient, r = node
        for q in offsets:
            if q != r:
                yield (i, j, orient, q), abs(q - r)

        if orient == 0:  # horizontal strip
            # Cross a vertical block boundary: entering vertical strip is at
            # its left or right edge; the horizontal row is unrestricted.
            for ni, col in ((i - 1, K - 1), (i + 1, 0)):
                nxt = (ni, j, 1, col)
                if nxt in allowed:
                    yield nxt, 1
            # Cross a horizontal block boundary: this strip must touch it.
            if r == 0:
                for q in offsets:
                    nxt = (i, j - 1, 1, q)
                    if nxt in allowed:
                        yield nxt, 1
            if r == K - 1:
                for q in offsets:
                    nxt = (i, j + 1, 1, q)
                    if nxt in allowed:
                        yield nxt, 1
        else:  # vertical strip
            # Cross a horizontal block boundary into the edge row.
            for nj, row in ((j - 1, K - 1), (j + 1, 0)):
                nxt = (i, nj, 0, row)
                if nxt in allowed:
                    yield nxt, 1
            # Cross a vertical block boundary when this strip is at its edge.
            if r == 0:
                for q in offsets:
                    nxt = (i - 1, j, 0, q)
                    if nxt in allowed:
                        yield nxt, 1
            if r == K - 1:
                for q in offsets:
                    nxt = (i + 1, j, 0, q)
                    if nxt in allowed:
                        yield nxt, 1

    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, node = heappop(heap)
        if d != dist[node]:
            continue
        if node == goal:
            return d
        for nxt, cost in neighbors(node):
            nd = d + cost
            if nd < dist.get(nxt, 10**100):
                dist[nxt] = nd
                heappush(heap, (nd, nxt))
    return md

