def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma divisible by 3."""
    root = isqrt(N)
    sieve = bytearray(b"\x01") * (root + 1)
    if root >= 0:
        sieve[:min(2, root + 1)] = b"\x00" * min(2, root + 1)
    primes = []
    for p in range(2, root + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= root:
                sieve[p*p:root+1:p] = b"\x00" * ((root-p*p)//p+1)

    vals = []
    i = 1
    while i <= N:
        v = N // i
        vals.append(v)
        i = N // v + 1
    idx = {v: j for j, v in enumerate(vals)}

    def initial(v, r):
        # Count integers in [2,v] congruent to r modulo 3.
        c = (v + 2 - r) // 3
        if r == 0:
            c -= 1
        elif r == 1:
            c -= 1
        return c

    g = [[initial(v, r) for v in vals] for r in range(3)]
    pref = [0, 0, 0]
    for p in primes:
        if p * p > N:
            break
        if p == 3:
            for j, v in enumerate(vals):
                if v < 9:
                    break
                y = v // 3
                removed = sum(g[r][idx[y]] for r in range(3))
                if y >= 2:
                    removed -= 1
                g[0][j] -= removed
        else:
            inv = 1 if p % 3 == 1 else 2
            for j, v in enumerate(vals):
                if v < p * p:
                    break
                iy = idx[v // p]
                for r in range(3):
                    src = r * inv % 3
                    g[r][j] -= g[src][iy] - pref[src]
        pref[p % 3] += 1

    def pi(x, r):
        if x < 2:
            return 0
        j = idx.get(x)
        if j is not None:
            return g[r][j]
        # All non-quotient endpoints in the recursion are at most sqrt(N).
        return sum(1 for p in primes if p <= x and p % 3 == r)

    def pi_all(x):
        return pi(x, 0) + pi(x, 1) + pi(x, 2)

    max_e = N.bit_length()
    choose = [1] * (max_e + 1)
    for e in range(1, max_e + 1):
        choose[e] = choose[e-1] * (M+e-1) % MOD * pow(e, MOD-2, MOD) % MOD

    def summed(bad):
        @lru_cache(None)
        def rec(x, last):
            if x == 1:
                return 1
            ans = 1
            lo = isqrt(x) + 1
            if bad:
                ans += M * (pi(x, 1) - pi(lo-1, 1))
                if lo <= 3 <= x:
                    ans += M
            else:
                ans += M * (pi_all(x) - pi_all(lo-1))
            for p in primes:
                if p <= last:
                    continue
                if p*p > x:
                    break
                power = p
                e = 1
                while power <= x:
                    allowed = (not bad or p == 3 or
                               (p % 3 == 1 and e % 3 != 2) or
                               (p % 3 == 2 and e % 2 == 0))
                    if allowed:
                        ans += choose[e] * rec(x // power, p)
                    e += 1
                    if power > x // p:
                        break
                    power *= p
            return ans % MOD
        return rec(N, 1)

    return (summed(False) - summed(True)) % MOD

