from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """ Play a modified tic-tac-toe game on a 3x3 grid where each cell has a value.

    Takahashi (first player) and Aoki (second player) take turns choosing white cells.
    When a player chooses a cell, they score the points in that cell and paint it their color
    (Takahashi: red, Aoki: blue).

    The game ends when:
    - A player gets 3 consecutive cells of their color (row/column/diagonal) - that player wins
    - All cells are painted - the player with higher total score wins

    Both players play optimally. The sum of all values in the grid is guaranteed to be odd.

    Args:
        grid: A 3x3 grid of integers representing cell values

    Returns:
        "Takahashi" if Takahashi wins, "Aoki" if Aoki wins

    >>> tic_tac_toe_winner([[0, 0, 0], [0, 1, 0], [0, 0, 0]])
    'Takahashi'
    >>> tic_tac_toe_winner([[-1, 1, 0], [-4, -2, -5], [-4, -1, -5]])
    'Aoki'
    """
    values = [grid[r][c] for r in range(3) for c in range(3)]
    lines = (
        (0, 1, 2), (3, 4, 5), (6, 7, 8),
        (0, 3, 6), (1, 4, 7), (2, 5, 8),
        (0, 4, 8), (2, 4, 6),
    )
    line_masks = tuple(sum(1 << cell for cell in line) for line in lines)
    full = (1 << 9) - 1
    # Any line win must be preferred to any completed-board score.
    win_value = 10**30

    @lru_cache(maxsize=None)
    def solve(takahashi: int, aoki: int) -> int:
        for mask in line_masks:
            if takahashi & mask == mask:
                return win_value
            if aoki & mask == mask:
                return -win_value

        occupied = takahashi | aoki
        if occupied == full:
            return sum(values[i] for i in range(9) if takahashi & (1 << i)) - sum(
                values[i] for i in range(9) if aoki & (1 << i)
            )

        takahashi_turn = occupied.bit_count() % 2 == 0
        remaining = full ^ occupied
        if takahashi_turn:
            return max(solve(takahashi | (1 << i), aoki) for i in range(9)
                       if remaining & (1 << i))
        return min(solve(takahashi, aoki | (1 << i)) for i in range(9)
                   if remaining & (1 << i))

    return "Takahashi" if solve(0, 0) > 0 else "Aoki"

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    sx, sy = S_x // K, S_y // K
    tx, ty = T_x // K, T_y // K

    def horizontal(i, j):
        return i % 2 == j % 2

    def strip_index(x, y, h):
        return y % K if h else x % K

    start_h = horizontal(sx, sy)
    goal_h = horizontal(tx, ty)
    start = (sx, sy, strip_index(S_x, S_y, start_h))
    goal = (tx, ty, strip_index(T_x, T_y, goal_h))

    span = abs(tx - sx) + abs(ty - sy)
    if span > 120:
        return span

    pad = 5
    xlo, xhi = min(sx, tx) - pad, max(sx, tx) + pad
    ylo, yhi = min(sy, ty) - pad, max(sy, ty) + pad
    if K <= 200:
        indices = range(K)
    else:
        indices = sorted({0, K - 1, start[2], goal[2]})
    index_values = tuple(indices)

    def is_h(node):
        return horizontal(node[0], node[1])

    def edges(node):
        i, j, k = node
        h = is_h(node)
        for kk in index_values:
            if kk != k:
                yield (i, j, kk), abs(kk - k)

        if h:
            if i + 1 <= xhi:
                yield (i + 1, j, 0), 1
            if i - 1 >= xlo:
                yield (i - 1, j, K - 1), 1
            if k == K - 1 and j + 1 <= yhi:
                for kk in index_values:
                    yield (i, j + 1, kk), 1
            if k == 0 and j - 1 >= ylo:
                for kk in index_values:
                    yield (i, j - 1, kk), 1
        else:
            if j + 1 <= yhi:
                yield (i, j + 1, 0), 1
            if j - 1 >= ylo:
                yield (i, j - 1, K - 1), 1
            if k == K - 1 and i + 1 <= xhi:
                for kk in index_values:
                    yield (i + 1, j, kk), 1
            if k == 0 and i - 1 >= xlo:
                for kk in index_values:
                    yield (i - 1, j, kk), 1

    distances = {start: 0}
    queue = [(0, start)]
    while queue:
        distance, node = heappop(queue)
        if distance != distances[node]:
            continue
        if node == goal:
            return distance
        for neighbor, cost in edges(node):
            candidate = distance + cost
            if candidate < distances.get(neighbor, 10**100):
                distances[neighbor] = candidate
                heappush(queue, (candidate, neighbor))

    return 0

