    for p in range(2, root + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= root:
                sieve[p*p:root+1:p] = b"\x00" * ((root-p*p)//p+1)
    pref_small = [[0] * (root + 1) for _ in range(3)]
    for x in range(2, root + 1):
        for r in range(3):
            pref_small[r][x] = pref_small[r][x-1]
        if sieve[x]:
            pref_small[x % 3][x] += 1

    vals = []
    i = 1
    while i <= N:
        v = N // i
        vals.append(v)
        i = N // v + 1
    idx = {v: j for j, v in enumerate(vals)}

    def initial(v, r):
        if r == 0:
            return v // 3
        if r == 1:
            return (v + 2) // 3 - 1
        return (v + 1) // 3

    g = [[initial(v, r) for v in vals] for r in range(3)]
    pref = [0, 0, 0]
    for p in primes:
        if p * p > N:
            break
        if p == 3:
            for j, v in enumerate(vals):
                if v < 9:
                    break
                y = v // 3
                removed = sum(g[r][idx[y]] for r in range(3))
                if y >= 2:
                    removed -= 1
                g[0][j] -= removed
        else:
            inv = 1 if p % 3 == 1 else 2
            for j, v in enumerate(vals):
                if v < p * p:
                    break
                iy = idx[v // p]
                for r in range(3):
                    src = r * inv % 3
                    g[r][j] -= g[src][iy] - pref[src]
        pref[p % 3] += 1

    def pi(x, r):
        if x < 2:
            return 0
        j = idx.get(x)
        if j is not None:
            return g[r][j]
        if x <= root:
            return pref_small[r][x]
        return g[r][idx[N // (N // x)]]

    def pi_all(x):
        return pi(x, 0) + pi(x, 1) + pi(x, 2)

    choose = [1] * (N.bit_length() + 1)
    for e in range(1, len(choose)):
        choose[e] = choose[e-1] * (M+e-1) % MOD * pow(e, MOD-2, MOD) % MOD

    def summed(bad):
        @lru_cache(None)
        def rec(x, last):
            if x == 1:
                return 1
            ans = 1
            lo = isqrt(x) + 1
            if bad:
                ans += M * (pi(x, 1) - pi(lo-1, 1))
                if lo <= 3 <= x:
                    ans += M
            else:
                ans += M * (pi_all(x) - pi_all(lo-1))
            start = bisect_right(primes, last)
            for p in primes[start:]:
                if p*p > x:
                    break
                power = p
                e = 1
                while power <= x:
                    allowed = (not bad or p == 3 or
                               (p % 3 == 1 and e % 3 != 2) or
                               (p % 3 == 2 and e % 2 == 0))
                    if allowed:
                        ans += choose[e] * rec(x // power, p)
                    e += 1
                    if power > x // p:
                        break
                    power *= p
            return ans % MOD
        return rec(N, 1)

    return (summed(False) - summed(True)) % MOD

