from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=None)
def _count_for_signature(n: int, signature: tuple[int, ...]) -> int:
    limit = isqrt(10 ** n - 1)
    total = 0
    for root in range(limit + 1):
        text = str(root * root)
        counts = [0] * 10
        for digit in text:
            counts[ord(digit) - 48] += 1
        counts[0] += n - len(text)
        if tuple(counts) == signature:
            total += 1
    return total


def count_square_permutations(n: int, s: str) -> int:
    """Count distinct square values obtainable by permuting the given digits."""
    counts = [0] * 10
    for digit in s:
        counts[ord(digit) - 48] += 1
    return _count_for_signature(n, tuple(counts))

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """ Count the number of ways to make K moves on a grid starting from any empty cell.

    The grid has H rows and W columns. Each cell is either empty ('.') or blocked ('#').
    A path consists of K+1 cells (starting cell + K moves) where:
    - All cells in the path are empty
    - Consecutive cells are adjacent (up, down, left, or right)
    - No cell is visited more than once in the path

    Args:
        H: Number of rows (1 <= H <= 10)
        W: Number of columns (1 <= W <= 10)
        K: Number of moves (1 <= K <= 11)
        grid: List of H strings, each of length W, representing the grid

    Returns:
        The number of valid paths of length K+1

    >>> count_paths(2, 2, 2, ['.#', '..'])
    2
    >>> count_paths(2, 3, 1, ['.#.', '#.#'])
    0
    """
    cells = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] == ".":
                cells[(r, c)] = len(cells)

    neighbors = [[] for _ in cells]
    for (r, c), i in cells.items():
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            j = cells.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    total = 0

    def extend(cell: int, remaining: int, visited: int) -> int:
        if remaining == 0:
            return 1
        count = 0
        for nxt in neighbors[cell]:
            bit = 1 << nxt
            if not visited & bit:
                count += extend(nxt, remaining - 1, visited | bit)
        return count

    for start in range(len(cells)):
        total += extend(start, K, 1 << start)
    return total

