def count_square_permutations(n: int, s: str) -> int:
    """Given a string s of length n consisting of digits, find the number of unique square numbers
    that can be obtained by interpreting any permutation of the digits as a decimal integer.

    Leading zeroes are allowed, and different permutations resulting in the same integer
    are counted only once.
    """
    counts = [0] * 10
    for digit in s:
        counts[ord(digit) - 48] += 1
    return _count_for_signature(n, tuple(counts))

from functools import lru_cache
from math import isqrt
from bisect import bisect_right

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma divisible by 3."""
    root = isqrt(N)
    sieve = bytearray(b"\x01") * (root + 1)
    sieve[:min(2, root + 1)] = b"\x00" * min(2, root + 1)
    primes = []
    for p in range(2, root + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= root:
                sieve[p*p:root+1:p] = b"\x00" * ((root-p*p)//p+1)
    pref_small = [[0] * (root + 1) for _ in range(3)]
    for x in range(2, root + 1):
        for r in range(3):
            pref_small[r][x] = pref_small[r][x-1]
        if sieve[x]:
            pref_small[x % 3][x] += 1

    vals = []
    i = 1
    while i <= N:
        v = N // i
        vals.append(v)
        i = N // v + 1
    idx = {v: j for j, v in enumerate(vals)}

    def initial(v, r):
        if r == 0:
            return v // 3
        if r == 1:
            return (v + 2) // 3 - 1
        return (v + 1) // 3

    g = [[initial(v, r) for v in vals] for r in range(3)]
    pref = [0, 0, 0]
    for p in primes:
        if p * p > N:
            break
        if p == 3:
            for j, v in enumerate(vals):
                if v < 9:
                    break
                y = v // 3
                removed = g[0][idx[y]] + g[1][idx[y]] + g[2][idx[y]]
                if y >= 2:
                    removed -= 1
                g[0][j] -= removed
        else:
            inv = 1 if p % 3 == 1 else 2
            for j, v in enumerate(vals):
                if v < p * p:
                    break
                iy = idx[v // p]
                for r in range(3):
                    src = r * inv % 3
                    g[r][j] -= g[src][iy] - pref[src]
        pref[p % 3] += 1

    def pi(x, r):
        if x < 2:
            return 0
        j = idx.get(x)
        if j is not None:
            return g[r][j]
        if x <= root:
            return pref_small[r][x]
        return g[r][idx[N // (N // x)]]

    def pi_all(x):
        return pi(x, 0) + pi(x, 1) + pi(x, 2)

    choose = [1] * (N.bit_length() + 1)
    for e in range(1, len(choose)):
        choose[e] = choose[e-1] * (M+e-1) % MOD * pow(e, MOD-2, MOD) % MOD

    def summed(bad):
        @lru_cache(None)
        def rec(x, last):
            if x == 1:
                return 1
            ans = 1
            low = max(isqrt(x), last)
            if bad:
                ans += M * (pi(x, 1) - pi(low, 1))
                if low < 3 <= x:
                    ans += M
            else:
                ans += M * (pi_all(x) - pi_all(low))
            pos = bisect_right(primes, last)
            while pos < len(primes):
                p = primes[pos]
                if p*p > x:
                    break
                power = p
                e = 1
                while power <= x:
                    allowed = (not bad or p == 3 or
                               (p % 3 == 1 and e % 3 != 2) or
                               (p % 3 == 2 and e % 2 == 0))
                    if allowed:
                        ans += choose[e] * rec(x // power, p)
                    e += 1
                    if power > x // p:
                        break
                    power *= p
                pos += 1
            return ans % MOD
        return rec(N, 1)

    return (summed(False) - summed(True)) % MOD

