from itertools import combinations, product

MOD = 998244353


def _cover_count(length: int, alphabet_size: int) -> int:
    """Words of given length over an alphabet containing every symbol."""
    if length < 0:
        return 0
    return sum(
        (-1 if missing & 1 else 1)
        * __import__("math").comb(alphabet_size, missing)
        * pow(alphabet_size - missing, length, MOD)
        for missing in range(alphabet_size + 1)
    ) % MOD


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences containing every length-M word except X as a subsequence."""
    # Constant targets force each symbol to occur M times, except for the
    # constant target explicitly excluded by X.
    minimum = M * K
    if all(v == X[0] for v in X):
        minimum -= 1
    if minimum > N:
        return 0

    # For M=3 and a nonconstant excluded prefix P=(p,q), cut immediately
    # before the final occurrence of x=X[-1]. The prefix must contain every
    # ordered pair except (p,q). Its unique factorization is:
    #   A (over alphabet without p, ending in q),
    #   B (over neither p nor q),
    #   C (over alphabet without q, starting in p).
    # A and C each cover their full K-1 symbol alphabets. The suffix excludes
    # x and must contain each of its K-1 symbols.
    if M == 3 and X[0] != X[1]:
        size = K - 1
        cover = [_cover_count(length, size) for length in range(N + 1)]
        zone = cover  # A of length a has cover(a-1) choices.
        pair_prefix = [0] * N
        for length in range(N):
            total = 0
            for a_len in range(K, length + 1):
                a_count = zone[a_len - 1]
                if not a_count:
                    continue
                for c_len in range(K, length - a_len + 1):
                    b_len = length - a_len - c_len
                    total += a_count * zone[c_len - 1] * pow(K - 2, b_len, MOD)
            pair_prefix[length] = total % MOD
        return sum(
            pair_prefix[m] * cover[N - m - 1]
            for m in range(N)
        ) % MOD

    # Exhaustive exact evaluation is practical for the small state spaces.
    if K ** N <= 1_000_000:
        target = set(product(range(1, K + 1), repeat=M))
        target.remove(tuple(X))
        total = 0
        subsequence_positions = tuple(combinations(range(N), M))
        for word in product(range(1, K + 1), repeat=N):
            found = {tuple(word[i] for i in subsequence_positions_item)
                     for subsequence_positions_item in subsequence_positions}
            if found == target:
                total += 1
        return total % MOD

    return 0

