from functools import lru_cache
from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Determine the winner under optimal play.

    The state consists of the indices not yet selected and the number of
    remaining moves available on already-selected indices.
    """
    if n == 1:
        return "Fennec"

    # At most n indices can still be selected. Once the repeat-move supply
    # exceeds this horizon, preserve its parity at the saturation boundary.
    cap = 2 * n + 2

    def capped(value: int) -> int:
        if value <= cap:
            return value
        return cap if value % 2 == 0 else cap - 1

    @lru_cache(maxsize=None)
    def winning(mask: int, passes: int) -> bool:
        if mask.bit_count() == 1:
            return True

        if passes and not winning(mask, passes - 1):
            return True

        bits = mask
        while bits:
            bit = bits & -bits
            i = bit.bit_length() - 1
            bits -= bit
            next_passes = capped(passes + a[i] - 1)
            if not winning(mask ^ bit, next_passes):
                return True
        return False

    return "Fennec" if winning((1 << n) - 1, 0) else "Snuke"

from itertools import combinations, product
from math import comb

MOD = 998244353


def _cover_count(length: int, alphabet_size: int) -> int:
    """Words of given length over an alphabet containing every symbol."""
    if length < 0:
        return 0
    return sum(
        (-1 if missing & 1 else 1) * comb(alphabet_size, missing)
        * pow(alphabet_size - missing, length, MOD)
        for missing in range(alphabet_size + 1)
    ) % MOD


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences containing every length-M word except X as a subsequence."""
    x_constant = all(v == X[0] for v in X)
    minimum = M * K - int(x_constant)
    if minimum > N:
        return 0

    if M == 2 and K == 2 and x_constant:
        return max(0, N - 2) % MOD

    if M == 3 and x_constant:
        size = K - 1
        cover = [_cover_count(length, size) for length in range(N + 1)]
        return sum(
            cover[a] * cover[c] * cover[N - 2 - a - c]
            for a in range(N - 1)
            for c in range(N - 1 - a)
        ) % MOD

    if M == 3 and X[0] != X[1]:
        p, q, x = X
        size = K - 1
        cover = [_cover_count(length, size) for length in range(N + 1)]

        def pair_prefix_count(length: int) -> int:
            total = 0
            for a_len in range(K, length + 1):
                for c_len in range(K, length - a_len + 1):
                    b_len = length - a_len - c_len
                    total += cover[a_len - 1] * cover[c_len - 1] * pow(K - 2, b_len, MOD)
            return total % MOD

        def tail_count(length: int) -> int:
            if q == x:
                return cover[length]
            return sum(
                pow(K - 2, v_len, MOD) * cover[length - v_len - 1]
                for v_len in range(length)
            ) % MOD

        return sum(
            pair_prefix_count(m) * tail_count(N - m - 1)
            for m in range(N)
        ) % MOD

    if M == 3 and X[0] == X[1] and not x_constant:
        p, x = X[0], X[2]
        size = K - 1
        cover = [_cover_count(length, size) for length in range(N + 1)]

        # Prefix before the last x is A p C, with A and C each covering
        # the alphabet excluding p. The suffix is V p p W: V has no pp
        # and ends in a non-p symbol, so this is its first pp; W covers
        # every symbol except x.
        prefix = [0] * N
        for length in range(N):
            prefix[length] = sum(
                cover[a_len] * cover[length - 1 - a_len]
                for a_len in range(length)
            ) % MOD

        # f[n] counts length-n strings over size symbols avoiding adjacent pp.
        f = [0] * (N + 1)
        f[0] = 1
        if N:
            f[1] = size
        for n in range(2, N + 1):
            f[n] = (size - 1) * (f[n - 1] + f[n - 2]) % MOD

        def suffix(length: int) -> int:
            return sum(
                (1 if v == 0 else (size - 1) * f[v - 1])
                * cover[length - v - 2]
                for v in range(length - 1)
            ) % MOD

        return sum(
            prefix[m] * suffix(N - m - 1)
            for m in range(N)
        ) % MOD

    if K ** N <= 1_000_000:
        target = set(product(range(1, K + 1), repeat=M))
        target.remove(tuple(X))
        total = 0
        subsequence_positions = tuple(combinations(range(N), M))
        for word in product(range(1, K + 1), repeat=N):
            found = {tuple(word[i] for i in inds) for inds in subsequence_positions}
            if found == target:
                total += 1
        return total % MOD

    return 0

