from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    sx, sy = S_x // K, S_y // K
    tx, ty = T_x // K, T_y // K

    def horizontal(i, j):
        return i % 2 == j % 2

    def strip_index(x, y, h):
        return y % K if h else x % K

    start_h = horizontal(sx, sy)
    goal_h = horizontal(tx, ty)
    start = (sx, sy, strip_index(S_x, S_y, start_h))
    goal = (tx, ty, strip_index(T_x, T_y, goal_h))

    dx, dy = abs(tx - sx), abs(ty - sy)
    span = dx + dy
    if span > 120:
        # With alternating horizontal and vertical macro crossings, the
        # smaller axis may make excursions to avoid strip realignment. The
        # number of crossings on that axis must have the displacement's
        # parity and be within one of the larger-axis count.
        if dx >= dy:
            y_steps = max(dy, dx - 1)
            if (y_steps - dy) % 2:
                y_steps += 1
            return dx + y_steps
        x_steps = max(dx, dy - 1)
        if (x_steps - dx) % 2:
            x_steps += 1
        return dy + x_steps

    pad = 5
    xlo, xhi = min(sx, tx) - pad, max(sx, tx) + pad
    ylo, yhi = min(sy, ty) - pad, max(sy, ty) + pad
    if K <= 200:
        indices = range(K)
    else:
        indices = sorted({0, K - 1, start[2], goal[2]})
    index_values = tuple(indices)

    def is_h(node):
        return horizontal(node[0], node[1])

    def edges(node):
        i, j, k = node
        h = is_h(node)
        for kk in index_values:
            if kk != k:
                yield (i, j, kk), abs(kk - k)

        if h:
            if i + 1 <= xhi:
                yield (i + 1, j, 0), 1
            if i - 1 >= xlo:
                yield (i - 1, j, K - 1), 1
            if k == K - 1 and j + 1 <= yhi:
                for kk in index_values:
                    yield (i, j + 1, kk), 1
            if k == 0 and j - 1 >= ylo:
                for kk in index_values:
                    yield (i, j - 1, kk), 1
        else:
            if j + 1 <= yhi:
                yield (i, j + 1, 0), 1
            if j - 1 >= ylo:
                yield (i, j - 1, K - 1), 1
            if k == K - 1 and i + 1 <= xhi:
                for kk in index_values:
                    yield (i + 1, j, kk), 1
            if k == 0 and i - 1 >= xlo:
                for kk in index_values:
                    yield (i - 1, j, kk), 1

    distances = {start: 0}
    queue = [(0, start)]
    while queue:
        distance, node = heappop(queue)
        if distance != distances[node]:
            continue
        if node == goal:
            return distance
        for neighbor, cost in edges(node):
            candidate = distance + cost
            if candidate < distances.get(neighbor, 10**100):
                distances[neighbor] = candidate
                heappush(queue, (candidate, neighbor))

    return 0

