from functools import lru_cache
from math import isqrt
from bisect import bisect_right

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma divisible by 3."""
    if N <= 100000:
        choose = [1] * (N.bit_length() + 1)
        for e in range(1, len(choose)):
            choose[e] = choose[e-1] * (M+e-1) % MOD * pow(e, MOD-2, MOD) % MOD
        spf = list(range(N+1))
        for p in range(2, isqrt(N)+1):
            if spf[p] == p:
                for v in range(p*p, N+1, p):
                    if spf[v] == v:
                        spf[v] = p
        ans = 0
        for n in range(2, N+1):
            v = n
            weight = 1
            good = False
            while v > 1:
                p = spf[v]
                e = 0
                while v % p == 0:
                    v //= p
                    e += 1
                weight = weight * choose[e] % MOD
                if p % 3 == 1 and e % 3 == 2:
                    good = True
                elif p % 3 == 2 and e % 2 == 1:
                    good = True
            if good:
                ans += weight
        return ans % MOD

    root = isqrt(N)
    sieve = bytearray(b"\x01") * (root + 1)
    sieve[:min(2, root + 1)] = b"\x00" * min(2, root + 1)
    primes = []
    for p in range(2, root + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= root:
                sieve[p*p:root+1:p] = b"\x00" * ((root-p*p)//p+1)
    pref_small = [[0] * (root + 1) for _ in range(3)]
    for x in range(2, root + 1):
        for r in range(3):
            pref_small[r][x] = pref_small[r][x-1]
        if sieve[x]:
            pref_small[x % 3][x] += 1

    vals = []
    i = 1
    while i <= N:
        v = N // i
        vals.append(v)
        i = N // v + 1
    idx = {v: j for j, v in enumerate(vals)}

    def initial(v, r):
        if r == 0:
            return v // 3
        if r == 1:
            return (v + 2) // 3 - 1
        return (v + 1) // 3

    g = [[initial(v, r) for v in vals] for r in range(3)]
    pref = [0, 0, 0]
    for p in primes:
        if p * p > N:
            break
        if p == 3:
            for j, v in enumerate(vals):
                if v < 9:
                    break
                y = v // 3
                removed = g[0][idx[y]] + g[1][idx[y]] + g[2][idx[y]]
                if y >= 2:
                    removed -= 1
                g[0][j] -= removed
        else:
            inv = 1 if p % 3 == 1 else 2
            for j, v in enumerate(vals):
                if v < p * p:
                    break
                iy = idx[v // p]
                for r in range(3):
                    src = r * inv % 3
                    g[r][j] -= g[src][iy] - pref[src]
        pref[p % 3] += 1

    def pi(x, r):
        if x < 2:
            return 0
        j = idx.get(x)
        if j is not None:
            return g[r][j]
        if x <= root:
            return pref_small[r][x]
        return g[r][idx[N // (N // x)]]

    def pi_all(x):
        return pi(x, 0) + pi(x, 1) + pi(x, 2)

    choose = [1] * (N.bit_length() + 1)
    for e in range(1, len(choose)):
        choose[e] = choose[e-1] * (M+e-1) % MOD * pow(e, MOD-2, MOD) % MOD

    @lru_cache(None)
    def rec(x, last):
        if x == 1:
            return (1, 1)
        total = 1
        badsum = 1
        low = max(isqrt(x), last)
        total += M * (pi_all(x) - pi_all(low))
        badsum += M * (pi(x, 1) - pi(low, 1))
        if low < 3 <= x:
            badsum += M
        pos = bisect_right(primes, last)
        while pos < len(primes):
            p = primes[pos]
            if p*p > x:
                break
            power = p
            e = 1
            while power <= x:
                child_total, child_bad = rec(x // power, p)
                term = choose[e]
                total += term * child_total
                allowed = (p == 3 or
                           (p % 3 == 1 and e % 3 != 2) or
                           (p % 3 == 2 and e % 2 == 0))
                if allowed:
                    badsum += term * child_bad
                e += 1
                if power > x // p:
                    break
                power *= p
            pos += 1
        return (total % MOD, badsum % MOD)

    total, bad = rec(N, 1)
    return (total - bad) % MOD

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    sx, sy = S_x // K, S_y // K
    tx, ty = T_x // K, T_y // K

    def horizontal(i, j):
        return i % 2 == j % 2

    def strip_index(x, y, h):
        return y % K if h else x % K

    sh, th = horizontal(sx, sy), horizontal(tx, ty)
    sk, tk = strip_index(S_x, S_y, sh), strip_index(T_x, T_y, th)
    start, goal = (sx, sy, sk), (tx, ty, tk)
    dx, dy = abs(tx - sx), abs(ty - sy)
    span = dx + dy

    if span > 120:
        # A path with no within-block strip shifts alternates its crossing
        # axes. Counts on each axis must match the signed displacement parity,
        # and an alternating word can have axis counts differing by at most 1.
        # If its first/last axis is perpendicular to the endpoint tile's long
        # direction, align that endpoint strip to the nearest block edge.
        start_free_axis = 0 if sh else 1  # 0=x, 1=y
        goal_free_axis = 0 if th else 1
        start_penalty = min(sk, K - 1 - sk)
        goal_penalty = min(tk, K - 1 - tk)
        best = 10**100
        for nx in range(dx, dx + 10, 2):
            for ny in range(dy, dy + 10, 2):
                if abs(nx - ny) > 1:
                    continue
                if nx == ny:
                    patterns = ((0, 1), (1, 0))  # first and last axis
                elif nx > ny:
                    patterns = ((0, 0),)
                else:
                    patterns = ((1, 1),)
                for first, last in patterns:
                    cost = nx + ny
                    if first != start_free_axis:
                        cost += start_penalty
                    if last != goal_free_axis:
                        cost += goal_penalty
                    best = min(best, cost)
        return best

    # For nearby blocks, Dijkstra runs on the exact strip graph. Strip
    # offsets are compressed to endpoint and boundary offsets; all edge costs
    # are linear between these breakpoints.
    indices = sorted({0, K - 1, sk, tk})
    index_values = tuple(indices)

    def is_h(node):
        return horizontal(node[0], node[1])

    def edges(node):
        i, j, k = node
        h = is_h(node)
        for kk in index_values:
            if kk != k:
                yield (i, j, kk), abs(kk - k)
        if h:
            yield (i + 1, j, 0), 1
            yield (i - 1, j, K - 1), 1
            if k == K - 1:
                for kk in index_values:
                    yield (i, j + 1, kk), 1
            if k == 0:
                for kk in index_values:
                    yield (i, j - 1, kk), 1
        else:
            yield (i, j + 1, 0), 1
            yield (i, j - 1, K - 1), 1
            if k == K - 1:
                for kk in index_values:
                    yield (i + 1, j, kk), 1
            if k == 0:
                for kk in index_values:
                    yield (i - 1, j, kk), 1

    distances = {start: 0}
    queue = [(0, start)]
    while queue:
        distance, node = heappop(queue)
        if distance != distances[node]:
            continue
        if node == goal:
            return distance
        for neighbor, cost in edges(node):
            candidate = distance + cost
            if candidate < distances.get(neighbor, 10**100):
                distances[neighbor] = candidate
                heappush(queue, (candidate, neighbor))
    return 0

